import sys
from collections import deque


def connected(n, edges, skip, a, b):
    adj = [[] for _ in range(n + 1)]
    for i, (u, v) in enumerate(edges):
        if i == skip:
            continue
        adj[u].append(v)
        adj[v].append(u)
    seen = [False] * (n + 1)
    seen[a] = True
    q = deque([a])
    while q:
        x = q.popleft()
        if x == b:
            return True
        for y in adj[x]:
            if not seen[y]:
                seen[y] = True
                q.append(y)
    return False


def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    m = int(data[1])
    edges = [(int(data[2 + 2 * i]), int(data[3 + 2 * i])) for i in range(m)]
    comp = [0] * (n + 1)
    c = 0
    for s in range(1, n + 1):
        if comp[s] == 0:
            c += 1
            for t in range(1, n + 1):
                if comp[t] == 0 and connected(n, edges, -1, s, t):
                    comp[t] = c
    cyclic = set()
    for i, (u, v) in enumerate(edges):
        if u == v or connected(n, edges, i, u, v):
            cyclic.add(comp[u])
    print(len(cyclic))


main()
